const XLSX = require('xlsx');
const wb = XLSX.readFile('data/order_summary.xlsx');
wb.SheetNames.forEach(name => {
  console.log('Sheet:', name);
  const ws = wb.Sheets[name];
  const data = XLSX.utils.sheet_to_json(ws, { header: 1 });
  // Print as a formatted table
  const colWidths = [];
  data.forEach(row => {
    row.forEach((cell, i) => {
      const len = String(cell ?? '').length;
      colWidths[i] = Math.max(colWidths[i] || 0, len);
    });
  });
  data.forEach((row, ri) => {
    const line = row.map((cell, i) => String(cell ?? '').padEnd(colWidths[i])).join(' | ');
    console.log(line);
    if (ri === 0) console.log(colWidths.map(w => '-'.repeat(w)).join('-+-'));
  });
  console.log();
});
"

cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('data/order_summary.xlsx');
const ws = wb.Sheets['Orders'];
const data = XLSX.utils.sheet_to_json(ws, { header: 1 });

// Find the header row to get column indices
const headers = data[0];
const orderIdCol = headers.indexOf('Order ID');
const statusCol = headers.indexOf('Status');

let updated = false;
for (let i = 1; i < data.length; i++) {
  if (data[i][orderIdCol] === 'ORD-6C71B1') {
    console.log('Before:', data[i][orderIdCol], '-', data[i][statusCol]);
    data[i][statusCol] = 'confirmed';
    console.log('After:', data[i][orderIdCol], '-', data[i][statusCol]);
    updated = true;
    break;
  }
}

if (updated) {
  const newWs = XLSX.utils.aoa_to_sheet(data);
  wb.Sheets['Orders'] = newWs;
  XLSX.writeFile(wb, 'data/order_summary.xlsx');
  console.log('File saved successfully.');
} else {
  console.log('Order not found.');
}
"
